using System.IO;using System.Windows;using System.Windows.Controls;using System.Windows.Documents;using System.Windows.Media;using System.Windows.Media.Imaging;using VoiceBridge.App;using VoiceBridge.App.Room;using VoiceBridge.App.Audio;using VoiceBridge.Core;
internal static class Program{
[STAThread] static void Main(string[] args){
 Velopack.VelopackApp.Build().SetAutoApplyOnStartup(false).Run();var app=new App();app.InitializeComponent();var window=new MainWindow(new ProfileStore(Path.Combine(Path.GetTempPath(),"VoiceBridge-layout-only.json")));var root=(DockPanel)window.Content;window.Content=null;root.Background=Brushes.Black;root.SetValue(TextElement.FontFamilyProperty,window.FontFamily);root.SetValue(TextElement.FontSizeProperty,14d);root.SetValue(TextElement.ForegroundProperty,window.Foreground);
 ((Grid)window.FindName("LobbyView")).Visibility=Visibility.Collapsed;((Grid)window.FindName("RoomView")).Visibility=Visibility.Visible;((TextBlock)window.FindName("ViewTitle")).Text="界面验证 · 合成数据";((TextBlock)window.FindName("ViewHint")).Text="仅检查布局，没有麦克风、音乐或网络采集";
 var members=Enumerable.Range(0,8).Select(i=>new MemberRow(new RoomMember(i.ToString("x32"),i==1?"较长昵称的合成成员用于检查换行":"合成成员 "+(i+1),true,true,false,false,""),i==0,true,(_,_,_)=>{})).ToArray();((ItemsControl)window.FindName("MemberList")).ItemsSource=members;
 ((ComboBox)window.FindName("SourceBox")).ItemsSource=new[]{new AudioSource("synthetic","合成音源 · 无设备采集",false,[])};((ComboBox)window.FindName("SourceBox")).SelectedIndex=0;((TextBlock)window.FindName("SourceCountText")).Text="1 个合成音源";
 var output=Path.GetFullPath(args[0]);Directory.CreateDirectory(output);var results=new List<object>();foreach(double scale in new[]{1d,1.25,1.5,2d}){
 VisualTreeHelper.SetRootDpi(root,new DpiScale(scale,scale));root.Width=1060;root.Height=730;root.Measure(new Size(1060,730));root.Arrange(new Rect(0,0,1060,730));root.UpdateLayout();
 var controls=new Dictionary<string,Rect>();foreach(string name in new[]{"MicButton","TalkModeBox","MicGainSlider","SpeakerGainSlider","LeaveButton","MusicButton","MusicGainSlider"}){var e=(FrameworkElement)window.FindName(name);var at=e.TransformToAncestor(root).Transform(new Point());var rect=new Rect(at,new Size(e.ActualWidth,e.ActualHeight));if(rect.Left<0||rect.Top<0||rect.Right>1061||rect.Bottom>731||rect.Width<1)throw new Exception("Control outside rendered root: "+name);controls[name]=rect;}
 int width=(int)Math.Ceiling(1060*scale),height=(int)Math.Ceiling(730*scale);var bitmap=new RenderTargetBitmap(width,height,96*scale,96*scale,PixelFormats.Pbgra32);bitmap.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(output,"native-dpi-"+(scale*100).ToString("0")+".png")))encoder.Save(file);results.Add(new{scale,pixels=new[]{width,height},actualDpi=VisualTreeHelper.GetDpi(root).PixelsPerDip,controls});}
 File.WriteAllText(Path.Combine(output,"layout-report.json"),System.Text.Json.JsonSerializer.Serialize(new{passed=true,offscreenWpfRendering=true,physicalMonitorSwitch=false,microphoneOpened=false,results}));Console.WriteLine("Native WPF 100/125/150/200 rendering passed");app.Shutdown();
}}
